import ApplicationServices
import Foundation

func pressButton(_ title: String) {
    let app = AXUIElementCreateApplication(35695)
    var winRef: CFTypeRef?
    AXUIElementCopyAttributeValue(app, kAXWindowsAttribute as CFString, &winRef)
    guard let win = (winRef as? [AXUIElement])?.first else { return }
    var childrenRef: CFTypeRef?
    AXUIElementCopyAttributeValue(win, kAXChildrenAttribute as CFString, &childrenRef)
    guard let children = childrenRef as? [AXUIElement] else { return }
    func search(_ el: AXUIElement) -> AXUIElement? {
        var roleRef: CFTypeRef?; AXUIElementCopyAttributeValue(el, kAXRoleAttribute as CFString, &roleRef)
        var descRef: CFTypeRef?; AXUIElementCopyAttributeValue(el, kAXDescriptionAttribute as CFString, &descRef)
        if (roleRef as? String) == (kAXButtonRole as String) && (descRef as? String) == title { return el }
        var childRef: CFTypeRef?
        if AXUIElementCopyAttributeValue(el, kAXChildrenAttribute as CFString, &childRef) == .success, let kids = childRef as? [AXUIElement] {
            for k in kids { if let f = search(k) { return f } }
        }
        return nil
    }
    for c in children {
        if let b = search(c) {
            AXUIElementPerformAction(b, kAXPressAction as CFString)
            print("pressed")
            return
        }
    }
}
